//! This port's Fuse results against `fixtures/search/fuse.json`, generated by Fuse.js 7.1.0.

use serde::Deserialize;

use super::super::fixture_test::{read, scores_match};
use super::search;

/// The generated `fixtures/search/fuse.json`.
#[derive(Deserialize)]
struct Fixture {
    corpus: Vec<String>,
    queries: Vec<Query>,
}

#[derive(Deserialize)]
struct Query {
    query: String,
    results: Vec<ResultEntry>,
}

#[derive(Deserialize)]
struct ResultEntry {
    #[serde(rename = "refIndex")]
    ref_index: usize,
    score: f64,
}

fn docs(fixture: &Fixture) -> Vec<&str> {
    fixture.corpus.iter().map(String::as_str).collect()
}

#[test]
fn indices_and_order_match_fuse_exactly() {
    let fixture: Fixture = read("search/fuse.json");
    let docs = docs(&fixture);
    for query in &fixture.queries {
        let actual: Vec<usize> = search(&docs, &query.query)
            .iter()
            .map(|result| result.ref_index)
            .collect();
        let expected: Vec<usize> = query
            .results
            .iter()
            .map(|result| result.ref_index)
            .collect();
        assert_eq!(actual, expected, "indices for {:?}", query.query);
    }
}

#[test]
fn scores_match_fuse_within_two_ulps() {
    let fixture: Fixture = read("search/fuse.json");
    let docs = docs(&fixture);
    for query in &fixture.queries {
        let actual = search(&docs, &query.query);
        assert_eq!(
            actual.len(),
            query.results.len(),
            "result count for {:?}",
            query.query
        );
        for (index, (result, expected)) in actual.iter().zip(&query.results).enumerate() {
            assert!(
                scores_match(result.score, expected.score),
                "score {index} for {:?}: {} vs {}",
                query.query,
                result.score,
                expected.score
            );
        }
    }
}

#[test]
fn the_fixture_keeps_long_and_non_ascii_queries() {
    let fixture: Fixture = read("search/fuse.json");
    assert!(
        fixture
            .queries
            .iter()
            .any(|query| query.query.encode_utf16().count() > 32),
        "a query longer than one Bitap chunk"
    );
    assert!(
        fixture.queries.iter().any(|query| !query.query.is_ascii()),
        "a non-ASCII query"
    );
    assert!(
        fixture.corpus.iter().any(|entry| !entry.is_ascii()),
        "a non-ASCII corpus entry"
    );
}
